-- =====================================================================
-- GENERATED by sql/render.py — do not edit, re-render.
--   source:  sql/ddl/01_config_rule_registry.sql
--   target:  workspace.dq_triage  (prefix dq_)
--
-- Comments below still say {catalog} and still describe two schemas. They are the
